MASK32 = 0xFFFFFFFF


def signed32(value):
    value &= MASK32
    return value - 0x100000000 if value & 0x80000000 else value


def expected_result(op, a, b):
    a &= MASK32
    b &= MASK32

    if op == 0x0:
        result = a + b
    elif op == 0x1:
        result = a - b
    elif op == 0x2:
        result = a << (b & 0x1F)
    elif op == 0x3:
        result = a >> (b & 0x1F)
    elif op == 0x4:
        result = signed32(a) >> (b & 0x1F)
    elif op == 0x5:
        result = a ^ b
    elif op == 0x6:
        result = a | b
    elif op == 0x7:
        result = a & b
    elif op == 0x8:
        result = a * b
    elif op == 0x9:
        result = (signed32(a) * signed32(b)) >> 32
    elif op == 0xA:
        result = (signed32(a) * b) >> 32
    elif op == 0xB:
        result = (a * b) >> 32
    elif op == 0xC:
        if b == 0:
            result = MASK32
        elif a == 0x80000000 and b == MASK32:
            result = 0x80000000
        else:
            dividend = signed32(a)
            divisor = signed32(b)
            quotient = abs(dividend) // abs(divisor)
            result = -quotient if (dividend < 0) != (divisor < 0) else quotient
    elif op == 0xD:
        result = MASK32 if b == 0 else a // b
    elif op == 0xE:
        if b == 0:
            result = a
        elif a == 0x80000000 and b == MASK32:
            result = 0
        else:
            dividend = signed32(a)
            divisor = signed32(b)
            quotient = abs(dividend) // abs(divisor)
            quotient = -quotient if (dividend < 0) != (divisor < 0) else quotient
            result = dividend - quotient * divisor
    else:
        result = a if b == 0 else a % b

    return result & MASK32


