    a &= MASK32
    b &= MASK32
    dut.operand_a.value = a
    dut.operand_b.value = b
    dut.alu_op.value = op
    await Timer(1, unit="ns")

    expected = expected_result(op, a, b)
    observed = int(dut.result.value)
    assert observed == expected, (
        f"alu_op=0x{op:X}, operand_a=0x{a:08X}, operand_b=0x{b:08X}: "
        f"expected result 0x{expected:08X}, observed 0x{observed:08X}"
