import cocotb
from cocotb.triggers import Timer


MASK32 = 0xFFFFFFFF


def signed32(value):
    value &= MASK32
    return value - 0x100000000 if value & 0x80000000 else value


def expected_result(op, a, b):
    a &= MASK32
    b &= MASK32

    if op == 0x0:
        value = a + b
    elif op == 0x1:
        value = a - b
    elif op == 0x2:
        value = a << (b & 0x1F)
    elif op == 0x3:
        value = a >> (b & 0x1F)
    elif op == 0x4:
        value = signed32(a) >> (b & 0x1F)
    elif op == 0x5:
        value = a ^ b
    elif op == 0x6:
        value = a | b
    elif op == 0x7:
        value = a & b
    elif op == 0x8:
        value = a * b
    elif op == 0x9:
        value = (signed32(a) * signed32(b)) >> 32
    elif op == 0xA:
        value = (signed32(a) * b) >> 32
    elif op == 0xB:
        value = (a * b) >> 32
    elif op == 0xC:
        if b == 0:
            value = MASK32
        elif a == 0x80000000 and b == MASK32:
            value = 0x80000000
        else:
            dividend = signed32(a)
            divisor = signed32(b)
            quotient = abs(dividend) // abs(divisor)
            value = -quotient if (dividend < 0) != (divisor < 0) else quotient
    elif op == 0xD:
        value = MASK32 if b == 0 else a // b
    elif op == 0xE:
        if b == 0:
            value = a
        elif a == 0x80000000 and b == MASK32:
            value = 0
        else:
            dividend = signed32(a)
            divisor = signed32(b)
            quotient = abs(dividend) // abs(divisor)
            quotient = -quotient if (dividend < 0) != (divisor < 0) else quotient
            value = dividend - quotient * divisor
    else:  # REMU
        value = a if b == 0 else a % b

    return value & MASK32


async def check_alu(dut, op, a, b):
    a &= MASK32
    b &= MASK32

    dut.operand_a.value = a
    dut.operand_b.value = b
    dut.alu_op.value = op
    await Timer(1, unit="ns")

